<script>
(function () {
 const form = document.querySelector('form[action$="/checkout"]');
 if (!form) return;
 const delivery = form.querySelector('input[name="fulfilment_type"][value="delivery_request"]');
 const names = ['address_line','city','supply_state','postal_code'];
 function refresh() {
  const required = delivery.checked;
  names.forEach(n => { const input = form.querySelector('[name="'+n+'"]'); if (input) input.required = required; });
 }
 form.querySelectorAll('input[name="fulfilment_type"]').forEach(input => input.addEventListener('change',refresh));
 refresh();
})();
</script></section>
